const upsertProductContent = `-- name: UpsertProductContent :one

INSERT INTO catalog_product_content (product_id, locale, name, short_description, description, meta_title, meta_description, meta_keywords)
VALUES ($1, $2, $3, $4, $5, $6, $7, $8)
ON CONFLICT (product_id, locale) DO UPDATE
    SET name              = EXCLUDED.name,
        short_description = EXCLUDED.short_description,
        description       = EXCLUDED.description,
        meta_title        = EXCLUDED.meta_title,
        meta_description  = EXCLUDED.meta_description,
        meta_keywords     = EXCLUDED.meta_keywords,
        updated_at        = NOW()
RETURNING product_id, locale, name, description, meta_title, meta_description, created_at, updated_at, short_description, meta_keywords, search_tsv
`

type UpsertProductContentParams struct {
	ProductID        uuid.UUID             `json:"product_id"`
	Locale           string                `json:"locale"`
	Name             string                `json:"name"`
	ShortDescription pqtype.NullRawMessage `json:"short_description"`
	Description      pqtype.NullRawMessage `json:"description"`
	MetaTitle        sql.NullString        `json:"meta_title"`
	MetaDescription  sql.NullString        `json:"meta_description"`
	MetaKeywords     sql.NullString        `json:"meta_keywords"`
}

// ==================== Product Content (translatable fields) ==================== After Phase 3, translations are keyed by (product_id, locale) only - no per-store dimension - per-store text variation, if ever needed, would come back via a sibling override table, not this primary translation store
func (q *Queries) UpsertProductContent(ctx context.Context, arg UpsertProductContentParams) (ProductContent, error) {
	row := q.db.QueryRowContext(ctx, upsertProductContent,
		arg.ProductID,
		arg.Locale,
		arg.Name,
		arg.ShortDescription,
		arg.Description,
		arg.MetaTitle,
		arg.MetaDescription,
		arg.MetaKeywords,
	)
	var i ProductContent
	err := row.Scan(
		&i.ProductID,
		&i.Locale,
		&i.Name,
		&i.Description,
		&i.MetaTitle,
		&i.MetaDescription,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.ShortDescription,
		&i.MetaKeywords,
		&i.SearchTsv,
	)
	return i, err
}
